<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('purchasing.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'purchase_orders');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='create'){$q=$pdo->prepare('INSERT INTO purchase_orders(po_number,supplier_id,project_id,status,order_date,expected_date,delivery_address,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([op_code('PO'),fint('supplier_id'),fint('project_id'),'draft',date('Y-m-d'),fpost('expected_date')?:null,fpost('delivery_address')?:null,fpost('notes')?:null,$staff['id']]);flash('success','Purchase order created.');}elseif($a==='status'){$pdo->prepare('UPDATE purchase_orders SET status=? WHERE id=?')->execute([fpost('status'),fint('id')]);flash('success','PO status updated.');}staff_redirect('staff/pages/purchase-orders.php');}
$sup=db_rows($pdo,'SELECT id,company_name FROM suppliers WHERE is_active=1 ORDER BY company_name');$projects=project_options($pdo);$rows=db_rows($pdo,'SELECT po.*,s.company_name,p.project_code FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id LEFT JOIN projects p ON p.id=po.project_id ORDER BY po.updated_at DESC');$pageTitle='Purchase Orders';require __DIR__.'/../../includes/staff/header.php';module_head('Procurement','Purchase Orders','Raise and track project purchasing from draft through receipt.');?>
<section class="staff-panel"><h2>New purchase order</h2><form method="post" class="mini-form"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Supplier<select name="supplier_id" required><?php foreach($sup as $s):?><option value="<?=$s['id']?>"><?=h($s['company_name'])?></option><?php endforeach?></select></label><label>Project<select name="project_id"><option value="">General stock</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Expected date<input type="date" name="expected_date"></label><label>Delivery address<input name="delivery_address"></label><label>Notes<input name="notes"></label><button class="btn primary">Create PO</button></form></section>
<section class="staff-panel table-panel"><table><thead><tr><th>PO</th><th>Supplier</th><th>Project</th><th>Status</th><th>Total</th><th>Expected</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['po_number'])?></b></td><td><?=h($r['company_name'])?></td><td><?=h($r['project_code']?:'Stock')?></td><td><span class="pill"><?=h(str_replace('_',' ',$r['status']))?></span></td><td>RM <?=number_format($r['total_amount'],2)?></td><td><?=h($r['expected_date']?:'—')?></td><td><form method="post" class="toolbar"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['draft','pending_approval','approved','ordered','partially_received','received','cancelled'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><button class="btn">Save</button></form></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>